// Offline authored templates; generate-bank.mjs materializes three fixed instances per family.
export const templates={};
const add=(moduleId,family,difficulty,competence,make)=>{(templates[moduleId]??=[]).push({family,difficulty,competence,make});};
const Q=(prompt,expected)=>({prompt,expected});
const C=(prompt,correct,...others)=>({prompt,options:[correct,...others],correct:0});
const sum=a=>a.reduce((a,b)=>a+b,0);
