add('browser','prevent-default-link',3,2,n=>C(`Bubble-обработчик клика по ссылке /page/${n} вызывает event.preventDefault(), других обработчиков нет. Что предотвращается?`,'Стандартный переход по ссылке','Любое распространение события','Вызов текущего обработчика','Рендер всей страницы'));
add('browser','stop-propagation-parent',3,2,n=>C(`Вложенная кнопка вызывает stopPropagation() в своём click-обработчике. Родитель имеет bubble-click, capture нет. Сколько раз выполнится обработчик родителя при ${n} кликах по кнопке?`,'0',String(n),String(n+1),'Зависит только от CSS'));
add('browser','css-transform-flow-width',3,1,n=>Q(`Блок width:${n*100}px; transform:scaleX(2). Его исходный layout-размер не меняется. Сколько px ширины он занимает в обычном потоке?`,n*100));
add('browser','csrf-same-site-cookie',3,2,n=>C(`Браузер отправляет cookie при изменяющем запросе к /orders/${n}. Зачем проверять CSRF-токен помимо сессии?`,'Чтобы отличать разрешённое действие страницы от поддельного запроса','Чтобы увеличить размер cookie','Чтобы шифровать HTML','Чтобы заменить проверку прав'));
add('browser','xss-text-content',3,2,n=>C(`Нужно показать пользовательскую строку <script>${n}</script> как текст в обычном DOM-элементе. Что использовать?`,'textContent','innerHTML','eval','document.write'));
add('browser','preflight-not-business-request',3,2,n=>C(`Перед междоменным POST с X-Request-ID:${n} браузер выполняет preflight. Каким HTTP-методом?`,'OPTIONS','POST','DELETE','CONNECT'));
add('browser','aria-hidden-focus-risk',3,0,n=>C(`В контейнере aria-hidden="true" находится ${n} доступных по Tab кнопок. Какой риск?`,'Фокус может попасть на элементы, скрытые от дерева доступности','Tab гарантированно пропустит контейнер','Кнопки станут readonly','Браузер добавит им видимые подписи'));
// React.
