add('react','state-initializer-on-mount',1,1,n=>C(`React: useState(${n}) в одном и том же экземпляре компонента. Состояние изменено на ${n+1}. Сбрасывает ли обычный рендер его обратно на ${n}?`,'Нет','Да','Только при изменении CSS','Только при клике мышью'));
add('react','event-handler-function',1,0,n=>C(`React: функция submit отправляет заказ №${n}. Как вызвать её по клику, а не во время рендера?`,'onClick={submit}','onClick={submit()}','onClick={null}','onClick="submit"'));
add('react','fragment-no-wrapper',1,0,n=>Q(`React возвращает Fragment с ${n} элементами li. Сколько дополнительных DOM-обёрток создаёт Fragment?`,0));
add('react','props-downward-flow',1,0,n=>C(`Родитель хранит count=${n} и передаёт его ребёнку. Как ребёнку запросить изменение этого состояния?`,'Вызвать переданный родителем callback','Изменить props.count напрямую','Удалить родителя из DOM','Присвоить window.count'));
add('react','key-not-normal-prop',1,0,n=>C(`React: <Item key={${n}} id={${n}}/>. Доступно ли key в Item как обычное props.key?`,'Нет, key — специальное свойство React','Да, всегда','Только если id совпадает','Только в production'));
