add('react','controlled-checkbox-checked',1,0,n=>C(`React-форма содержит checkbox для опции №${n}, состояние — булево enabled. Какое свойство управляет отметкой?`,'checked={enabled}','value={enabled}','selected={enabled}','alt={enabled}'));
add('react','updater-compose-functions',2,1,n=>Q(`React: count=${n}; в одном обработчике setCount(c=>c*2); setCount(c=>c+1). Каково итоговое состояние?`,2*n+1));
add('react','replacement-after-updater',2,1,n=>Q(`React: count=${n}; setCount(c=>c+1); setCount(10). Каково итоговое состояние после этих обновлений в одном обработчике?`,10));
