add('react','key-change-resets-state',2,1,n=>C(`У Counter локальное состояние ${n}. Родитель меняет key с "a" на "b". Что происходит с этим экземпляром Counter?`,'Старый размонтируется, новый получит начальное состояние','Только изменится DOM-id','Состояние всегда сохранится','Удалятся все компоненты страницы'));
add('react','effect-cleanup-before-rerun',2,1,n=>C(`useEffect зависит от id=${n}. id изменился на ${n+1}, предыдущий эффект вернул cleanup. Какой порядок?`,'Сначала прежний cleanup, затем новый эффект','Только новый эффект','Сначала новый эффект, затем cleanup предыдущего','Cleanup вызовется только при перезапуске браузера'));
add('react','hook-order-invariant',2,2,n=>C(`Компонент для ${n} разных режимов вызывает useState внутри if. Почему это опасно?`,'При смене режима порядок вызова хуков может измениться','useState запрещён в функциях','if всегда вызывает рендер дважды','Режимы обязаны быть числами'));
add('react','memo-value-dependencies',2,2,n=>C(`useMemo считает total из prices=${n}-элементного массива. Какую зависимость нужно указать при неизменяемых обновлениях массива?`,'prices','Только prices.length, даже если меняются значения','Пустой массив всегда','Случайное число'));
add('react','lifting-state-shared',2,2,n=>C(`Два соседних компонента должны показывать одну выбранную запись №${n}. Где хранить их общее состояние?`,'В ближайшем общем предке либо общем хранилище','В двух несинхронизированных копиях','В CSS каждого компонента','В текстах DOM без React'));
add('react','zero-and-render',3,0,n=>C(`React: count=0; return <div>{count && <span>${n}</span>}</div>. Что попадёт в div?`,'Текст 0','Ничего','span','Текст false'));
add('react','effect-object-dependency',3,1,n=>C(`На каждом рендере создаётся config={id:${n}}. useEffect зависит от [config]. Что вызывает его повторные запуски?`,'Новая ссылка config при каждом рендере','Только изменение id','Только сетевые ошибки','Только ключ компонента'));
add('react','ref-callback-current-value',3,1,n=>Q(`React: ref.current=${n}; обработчик делает ref.current+=2. Чему равен ref.current сразу после обработчика?`,n+2));
add('react','stale-interval-closure',3,1,n=>C(`Эффект с [] создал interval, вызывающий setCount(count+1); count при создании равен ${n}. Какое обновление устраняет захваченный старый count?`,'setCount(c=>c+1)','setCount(count+1) без изменений','count++ без setCount','Изменение CSS interval'));
add('react','context-consumer-update',3,2,n=>C(`Context.Provider меняет value с ${n} на ${n+1}. Consumer читает контекст через useContext и обёрнут в memo. Получит ли он новое значение контекста?`,'Да','Нет, memo всегда блокирует контекст','Только после изменения key','Только при перезагрузке'));
add('react','usememo-mutated-dependency',3,2,n=>C(`useMemo зависит от [items]. items.push(${n}) меняет массив на месте, ссылка не меняется. Пересчитает ли useMemo значение именно из-за этого изменения ссылки?`,'Нет, ссылка не изменилась','Да, сравнение всегда глубокое','Да, push отправляет React-событие','Массив автоматически копируется'));
add('react','effect-unsubscribe-identity',3,1,n=>C(`Компонент ${n} создаёт handler в эффекте и передаёт его subscribe. Что передать unsubscribe в cleanup?`,'Тот же handler','Новый ()=>{}','Любую функцию с тем же именем','Строку "handler"'));
add('react','error-boundary-async-event',3,2,n=>C(`Обработчик клика запускает async-запрос №${n}, который отклонился. Как обработать ошибку внутри этого пути?`,'Перехватить её в async-обработчике и отобразить состояние ошибки','Рассчитывать только на Error Boundary для этого async-события','Удалить await и игнорировать Promise','Изменить key кнопки'));
add('react','list-key-insertion-state',3,0,n=>C(`Список из ${n} редактируемых строк использует key=index. В начало вставили новую строку. Какой риск для локального состояния строк?`,'Оно может связаться с другой записью','React гарантированно удалит все input','Порядок данных не изменится','Все значения автоматически сохранятся по id'));
