add('backend','cache-vary-user-risk',3,0,n=>C(`Общий кеш хранит /profile/${n} без учёта авторизации, а URL возвращает разные данные разным пользователям. Какой риск?`,'Выдача персональных данных другого пользователя','Только уменьшение размера JSON','Автоматический logout','Увеличение TLS-ключа'));
add('backend','read-your-writes-lag',3,1,n=>C(`API записал version=${n} на primary, затем прочитал с отстающей реплики. Почему может вернуться прежняя версия?`,'Реплика ещё не применила запись','JSON не поддерживает version','Commit всегда удаляет строку','HTTP запрещает последовательные запросы'));
add('backend','circuit-open-call-count',3,2,n=>Q(`Circuit breaker открыт и отклоняет запросы локально. Поступило ${n} запросов, half-open ещё не начался. Сколько вызовов уйдёт к зависимому сервису?`,0));
add('backend','saga-compensation-order',3,1,n=>C(`Saga: резерв товара №${n} успешен, платёж отклонён. Какое действие компенсирует резерв при отмене заказа?`,'Освободить зарезервированный товар','Ещё раз списать платёж','Считать заказ оплаченным','Удалить журналы'));
add('backend','max-payload-before-work',3,2,n=>C(`API ограничивает тело ${n} МБ. Клиент прислал ${n+1} МБ. Где применить ограничение для защиты ресурсов?`,'До дорогого разбора и выполнения бизнес-операции','Только после записи в БД','Только после отправки ответа','В CSS клиента'));
