add('infrastructure','memory-limit-exceed',2,0,n=>C(`Контейнер №${n} превысил жёсткий memory limit. Какой возможный результат?`,'OOM kill','Автоматическое увеличение лимита всегда','Перенос памяти в README','Гарантированная остановка всех узлов'));
add('infrastructure','readiness-excludes-traffic',2,2,n=>C(`Из ${n+1} pod один не проходит readiness. Как учитывать его в обычной балансировке Service?`,'Не направлять на него новый трафик','Направлять весь трафик только ему','Удалить все readiness-проверки','Изменить только логотип'));
add('infrastructure','config-rollback-revision',2,1,n=>C(`Образ v${n} откатывают, но конфиг несовместим со старой версией. Что требуется?`,'Вернуть согласованную версию образа и конфига','Откатить только имя pod','Всегда оставить новый конфиг','Очистить все логи'));
add('infrastructure','backup-restore-verification',2,2,n=>C(`Есть ${n} успешных отчёта о backup. Как проверить, что данные реально восстановимы?`,'Проверить восстановление и целостность данных','Только проверить наличие имени файла','Считать отчёт достаточным без восстановления','Удалить исходную БД'));
add('infrastructure','graceful-drain-connections',2,2,n=>Q(`При graceful shutdown принято ${n} активных запросов, новые не принимаются. Все текущие успешно завершились. Сколько было прервано?`,0));
add('infrastructure','immutable-image-tag-risk',2,1,n=>C(`Тег app:release-${n} перезаписан другим образом. Почему тег не гарантирует прежний артефакт?`,'Тег изменяем, нужен сохранённый digest','Теги всегда неизменяемы','Имя репозитория шифрует содержимое','HTTP-кеш восстанавливает старый образ'));
add('infrastructure','slo-error-budget-remaining',3,2,n=>Q(`За окно допустимо ${n*10} ошибок, уже было ${n*10-3}. Сколько ошибок осталось в бюджете?`,3));
add('infrastructure','availability-percent-window',3,2,n=>Q(`За окно ${n*100} запросов, ${n*5} ошибок. Введите процент успешных.`,95));
add('infrastructure','terraform-plan-before-apply',3,1,n=>C(`Terraform plan для изменения №${n} показывает удаление критической БД, чего не требует задача. Что сделать перед apply?`,'Разобраться с причиной удаления и исправить план','Применить, не читая план','Изменить цвет вывода','Считать удаление всегда безвредным'));
add('infrastructure','distributed-lock-expiry',3,2,n=>C(`Воркер удерживал lease ${n} секунд, lease истёк, другой воркер получил его. Что защищает ресурс от поздней записи первого?`,'Проверка монотонного fencing token ресурсом','Только имя первого воркера','Случайный sleep после записи','Удаление журнала блокировок'));
add('infrastructure','dns-ttl-expiry',3,0,n=>Q(`DNS запись закеширована в t=${n*10} с TTL=60 секунд. При t=${n*10+40} сколько секунд TTL осталось?`,20));
add('infrastructure','retry-jitter-herd',3,2,n=>C(`После сбоя ${n*100} клиентов повторяют запрос одновременно каждые 2 секунды. Что уменьшит синхронизацию?`,'Случайный разброс задержек при ограниченных повторах','Ещё более одинаковые задержки','Отмена всех таймаутов','Вывод секретов в лог'));
add('infrastructure','rolling-unavailable-budget',3,1,n=>Q(`Deployment replicas=${n*4}, maxUnavailable=25%, maxSurge=0. Сколько реплик может быть недоступно в рамках этого лимита?`,n));
add('infrastructure','sigterm-before-sigkill',3,0,n=>C(`Сервис №${n} должен закончить текущие запросы при штатной остановке. Как обработать SIGTERM?`,'Прекратить новые запросы и завершить текущие в пределах grace period','Игнорировать сигнал бесконечно','Удалить конфиг до завершения','Всегда немедленно выполнить SIGKILL'));
add('infrastructure','replication-not-backup',3,2,n=>C(`Есть ${n} синхронизированных реплик БД. Почему это не заменяет backup при случайном DELETE?`,'Удаление может распространиться на все реплики','Реплика всегда хранит все исторические версии','DELETE работает только на одной реплике','Backup нужен только для логотипов'));
add('infrastructure','rate-capacity-after-loss',3,2,n=>Q(`Нагрузка ${n*100} запросов/с, после отказа доступно ${n*100-20}. Каков дефицит ёмкости в запросах/с?`,20));
// Test design.
add('test-design','inclusive-lower-valid',1,0,n=>Q(`Допустимы целые значения [${n*10}, ${n*10+9}]. Введите минимальное допустимое значение.`,n*10));
add('test-design','invalid-below-lower',1,0,n=>Q(`Поле принимает целые [${n*10}, ${n*10+9}]. Введите ближайшее недопустимое значение ниже диапазона.`,n*10-1));
add('test-design','inclusive-internal-values',1,0,n=>Q(`Допустимы целые [${n}, ${n+2}]. Сколько допустимых целых в диапазоне?`,3));
add('test-design','empty-required-field',1,1,n=>C(`Поле «Имя» обязательно; максимальная длина ${n*10}. Какой результат ожидается для пустой строки?`,'Ошибка обязательного поля','Успешное сохранение','Автоматически любое имя','Отключение всех проверок'));
add('test-design','exclusive-upper-bound',1,0,n=>Q(`Допустимы целые x при 0<=x<${n*10}. Введите наибольшее допустимое x.`,n*10-1));
add('test-design','requirement-traceability',1,1,n=>C(`Для требования R${n} нужно понимать покрытие. Что связать с тестами?`,'Идентификатор и проверяемое условие требования','Только фамилию автора','Только цвет отчёта','Случайное число'));
add('test-design','negative-permission-case',1,1,n=>C(`Удаление ресурса №${n} разрешено только владельцу. Какой отрицательный случай нужен?`,'Попытка удаления другим пользователем','Только повторное чтение владельцем','Изменение цвета кнопки','Только правильный пароль владельца'));
add('test-design','equivalence-valid-representative',1,0,n=>C(`Все целые возраста [${n*10}, ${n*10+9}] обрабатываются одинаково по правилу. Какой пример представляет допустимый класс?`,String(n*10+4),String(n*10-1),String(n*10+10),'Пустая строка'));
add('test-design','expected-versus-actual',1,1,n=>C(`По требованиям итог ${n}, система вернула ${n+1}. Что фиксировать в дефекте?`,'Ожидаемый и фактический результат с шагами','Только слово «не работает»','Только число тестов','Только время открытия браузера'));
add('test-design','unreachable-transition',1,0,n=>C(`Заказ №${n} отменён. Требование запрещает отправку отменённого заказа. Какой переход проверить как недопустимый?`,'Отменён → отправлен','Оплачен → отправлен','Создан → оплачен','Отправлен → доставлен'));
add('test-design','string-length-boundary',2,0,n=>Q(`Максимальная длина строки ${n*10}, пустая допустима. В наборе длин [0, ${n*10-1}, ${n*10}, ${n*10+1}] сколько допустимых?`,3));
add('test-design','two-factor-full-combinations',2,0,n=>Q(`Есть ${n} браузера и 2 роли пользователя. Все комбинации допустимы. Сколько тестов в полном переборе комбинаций?`,2*n));
add('test-design','decision-rule-and',2,0,n=>Q(`Скидка требует двух условий A и B. Все четыре сочетания проверены. Сколько сочетаний дают скидку? Номер правила ${n}.`,1));
add('test-design','decision-rule-or',2,0,n=>Q(`Доступ даётся при A OR B. Все четыре сочетания булевых условий допустимы. Сколько дают доступ? Правило №${n}.`,3));
add('test-design','priority-business-impact',2,2,n=>C(`Ограничено ${n} минутами: ошибка списывает чужие деньги, другая меняет отступ. Какой риск приоритетнее при прочих равных?`,'Некорректное списание денег','Отступ','Оба всегда одинаковы','Только более короткий тест'));
add('test-design','requirement-rounding',2,1,n=>C(`Цена рассчитана как ${n}.125. Требование не задаёт округление. Что сделать для однозначного оракула?`,'Уточнить точность и правило округления','Всегда округлять случайно','Признать любое число верным','Проверять только HTTP-статус'));
add('test-design','independent-test-precondition',2,1,n=>C(`Тест T${n} требует заказ в статусе «оплачен». Как сделать его независимым от порядка запуска?`,'Самостоятельно подготовить этот статус','Зависеть от успеха предыдущего теста','Запретить повторные запуски','Вставить случайную задержку'));
add('test-design','boundary-closed-open',2,0,n=>Q(`Допустимы целые ${n}<=x<${n+3}. Проверки: ${n-1}, ${n}, ${n+2}, ${n+3}. Сколько должно отклоняться?`,2));
add('test-design','pairwise-not-all-triples',3,2,n=>C(`Для ${n+2} параметров набор покрывает все пары значений. Что он не гарантирует автоматически?`,'Покрытие всех троек значений','Наличие хотя бы одного теста','Наличие проверенных пар','Возможность выполнить тест'));
add('test-design','metamorphic-permutation-sum',3,1,n=>C(`Функция суммирует массив из ${n} чисел. Какой метаморфный инвариант проверить?`,'Перестановка элементов не меняет сумму','Перестановка всегда удваивает сумму','Сумма всегда равна длине','Сумма всегда отрицательна'));
add('test-design','metamorphic-idempotent-normalize',3,1,n=>C(`Нормализация N строки №${n} должна быть идемпотентной. Какое свойство проверить?`,'N(N(x)) = N(x)','N(x) = x всегда','N(N(x)) всегда пусто','Длина N(x) всегда растёт'));
add('test-design','concurrency-invariant',3,2,n=>C(`Склад имеет ${n} единиц; два клиента одновременно покупают весь остаток. Какой инвариант нужен?`,'Суммарно продано не больше исходного остатка','Оба запроса обязательно успешны','Все ответы обязательно одинаковы','Остаток может быть отрицательным'));
add('test-design','invalid-data-no-side-effect',3,1,n=>C(`Запрос с недопустимой суммой -${n} должен отклоняться. Что проверить помимо ошибки?`,'Отсутствие побочных изменений данных','Только цвет ошибки','Только число слов ответа','Только скорость клиента'));
add('test-design','timeouts-unknown-outcome',3,2,n=>C(`Клиент получил таймаут при создании заказа №${n}. Какой случай нужен для проверки надёжности?`,'Повтор после возможного успешного выполнения на сервере','Только повтор до отправки запроса','Только пустой список заказов','Только настройка шрифта'));
add('test-design','multi-condition-mcdc',3,0,n=>C(`Решение A AND B в правиле №${n}. Пары (T,T)/(F,T) меняют только A. Что они демонстрируют?`,'Независимое влияние A на результат','Независимое влияние только B','Все возможные сочетания трёх условий','Отсутствие зависимости от A'));
add('test-design','state-path-order',3,0,n=>C(`Разрешены создан→оплачен→отправлен для заказа №${n}, прямой создан→отправлен запрещён. Какую последовательность принять?`,'Создан, оплачен, отправлен','Создан, отправлен','Отправлен, создан','Оплачен, создан, отправлен'));
add('test-design','boundary-risk-zero',3,2,n=>C(`Покупка разрешена при остатке>=1. Остаток сейчас ${n}. Какое пограничное значение критично для запрета покупки?`,'0',String(n),String(n+2),'100'));
add('test-design','coverage-percent-requirements',3,2,n=>Q(`Есть ${n*10} обязательных правил. Тестами покрыто ${n*8}. Введите долю покрытых правил в процентах.`,80));
// Automation.
add('automation','parameter-cases-length',1,0,n=>Q(`Автотест запускается отдельно для каждого из ${n+2} значений параметра. Сколько тестовых случаев выполнится?`,n+2));
add('automation','assert-equality-result',1,0,n=>C(`В тесте assert.equal(actual, ${n}), actual=${n+1}. Как завершится проверка?`,'Упадёт','Пройдёт','Всегда пропустится','Изменит actual'));
add('automation','fixture-before-test',1,1,n=>C(`Тест №${n} требует существующего пользователя. Когда подготовить фикстуру?`,'До выполнения проверяемого действия','Только после assert','Только после падения','Только в другом независимом тесте'));
add('automation','test-user-unique-id',1,1,n=>C(`Одновременно запускаются ${n} тестов создания пользователя. Как уменьшить конфликты тестовых данных?`,'Отдельный уникальный идентификатор для каждого теста','Один общий email без очистки','Одинаковый пароль как ключ данных','Случайный sleep'));
add('automation','http-response-body-assert',1,2,n=>C(`API вернул 200 и поле count=${n}. Что проверить для контракта, если count обязателен и целый?`,'Наличие count и целочисленный тип','Только 200','Только длину URL','Только Content-Length'));
add('automation','failure-report-evidence',1,0,n=>C(`UI-тест №${n} упал. Что помогает воспроизвести дефект?`,'Шаг, фактическое состояние и диагностические данные','Только зелёный значок','Только число файлов','Удаление всех логов'));
add('automation','stable-testid-selector',1,0,n=>C(`У кнопки оплаты №${n} часто меняется CSS-класс. Какой селектор устойчив при принятом контракте test-id?`,'По стабильному data-testid','По случайному классу сборки','По третьему div на странице','По текущему цвету'));
add('automation','cleanup-after-failure',1,1,n=>C(`Тест создал ${n} временных записей и упал. Какой механизм запускает очистку независимо от успеха?`,'finally / гарантированный teardown','Только код после успешного assert','Ручная очистка раз в месяц','Удаление assert'));
add('automation','independent-order-run',1,1,n=>C(`Набор ${n} тестов проходит только в одном порядке. Что в первую очередь проверить?`,'Зависимости через общее состояние и данные','Цвет отчёта','Число комментариев','Размер README'));
add('automation','ci-fail-exit-code',1,2,n=>C(`CI-команда выполнила ${n} тестов, один упал. Какой exit code нужен для обозначения ошибки?`,'Ненулевой','Всегда 0','Пустая строка','Любая дата'));
add('automation','mock-call-count',2,0,n=>Q(`Мок функции отправки вызван в цикле for(i=0;i<${n};i++). Введите ожидаемое число вызовов.`,n));
add('automation','timeout-versus-sleep',2,0,n=>C(`Кнопка появляется не позднее ${n} секунд. Как ждать её в UI-тесте?`,'Ожидать условие видимости с таймаутом','Всегда sleep на случайные 10 секунд','Не ждать и сразу кликать координаты','Отключить проверку видимости'));
add('automation','transaction-fixture-isolation',2,1,n=>C(`Тест №${n} меняет БД внутри своей транзакции без отдельного commit приложения. Что изолирует его изменения после завершения?`,'Rollback транзакции в teardown','Commit в каждом assert','Общий пользователь без очистки','Удаление подключения до завершения записи'));
add('automation','parallel-worker-time',2,2,n=>Q(`Есть ${n*2} независимых тестов по 5 секунд; ${n} воркеров, равномерное распределение, накладных расходов нет. Введите общее время в секундах.`,10));
add('automation','flaky-repeat-no-proof',2,2,n=>C(`Тест упал, затем прошёл при ${n} повторе без изменений. Что это означает для исходной ошибки?`,'Она требует анализа; повтор не доказывает отсутствие дефекта','Первый запуск автоматически несуществующий','Можно всегда удалить тест','Дефект исправлен повтором по определению'));
add('automation','test-clock-controlled',2,1,n=>Q(`Фальшивые часы начинаются с ${n*10} секунд; переведены на 30 секунд вперёд. Каково новое время в секундах?`,n*10+30));
add('automation','contract-required-field-removal',2,2,n=>C(`API v${n+1} удалил обязательное поле контракта v${n}. Что должен сделать контрактный тест потребителя?`,'Выявить несовместимое изменение','Игнорировать любое отсутствие полей','Принять только по статусу 200','Заменить поле случайным'));
add('automation','retry-total-runtime',2,2,n=>Q(`Исходный запуск и ${n} повторов теста заняли по 2 секунды, пауз нет. Введите максимальное суммарное время.`,2*(n+1)));
add('automation','async-cleanup-await',3,1,n=>C(`Teardown удаляет ${n} записей асинхронно и возвращает Promise. Что нужно, чтобы следующий тест не начал работу до очистки?`,'Дождаться Promise очистки','Игнорировать Promise','Удалить await в каждом тесте','Вызвать очистку после отчёта'));
add('automation','race-test-barrier',3,0,n=>C(`Нужно проверить конкурентное обновление ${n} клиентов в определённой точке. Что делает сценарий управляемым?`,'Барьер/синхронизация в точке запуска операций','Случайные sleep без контроля','Последовательный запуск вместо конкуренции','Отключение проверок результата'));
add('automation','seeded-random-reproduction',3,1,n=>C(`Генератор тестовых данных случайно создал дефектный случай №${n}. Что сохранить для воспроизведения?`,'Seed и конкретный вход','Только слово «random»','Только дату','Только число тестов'));
add('automation','negative-assertion-observation',3,0,n=>C(`Проверяется, что после запрещённого действия запись №${n} не появилась. Что нужно для содержательной проверки?`,'Наблюдать итоговые данные после завершения действия','Проверить отсутствие до выполнения','Проверить только наличие кнопки','Сразу завершить тест до ответа'));
add('automation','polling-deadline-budget',3,0,n=>Q(`Проверка делает ${n} попыток мгновенного чтения; между соседними попытками ждёт 2 секунды. Сколько секунд ожидания всего?`,2*(n-1)));
add('automation','ci-shard-unique-coverage',3,2,n=>C(`В ${n} шардах некоторые тесты не запускаются, другие повторяются. Что проверить?`,'Полноту и непересечение распределения test-id','Только успех одного шарда','Только имя ветки','Только число воркеров'));
