add('integration-qa','qa-null-where-regression',3,IQ,n=>Q(`SQL-фикстура x: NULL, ${n}, ${n+1}. Автотест вызывает API для отсутствующих x; корректный фильтр IS NULL. Сколько объектов ожидать?`,1));
