add('integration-qa','qa-oracle-same-code-risk',3,['test-design','automation'],n=>C(`Ожидаемый результат теста №${n} вычисляется тем же ошибочным методом, что production. Какой риск?`,'Совпадение ошибок реализации и оракула','Гарантированная независимая проверка','Всегда падение теста','Автоматическое выявление всех дефектов'));
add('integration-qa','qa-transaction-partial-effect',3,IQ,n=>C(`Тест переводит ${n} единиц, внедряет сбой между списанием и зачислением. Требуется SQL-атомарность. Какой итог проверить?`,'Оба баланса исходные после rollback','Только списание сохранено','Только HTTP 500 без проверки БД','Случайный новый баланс'));
add('integration-qa','qa-sql-not-in-null-oracle',3,IQ,n=>Q(`A.id=[${n},${n+1}], запрет B.id=[NULL]. API должен исключать только совпавшие id через NOT EXISTS. Сколько объектов ожидает автотест?`,2));
add('integration-qa','qa-customer-isolated-data',3,['sql','automation'],n=>C(`Тест №${n} проверяет заказ своего пользователя, но SQL count считает все заказы общего окружения. Как исправить оракул?`,'Фильтровать по идентификаторам фикстуры теста','Удалять чужие заказы','Считать любое count успехом','Запретить параллельный CI навсегда'));
add('integration-qa','qa-boundary-price-zero',3,IQ,n=>C(`API допускает price>=0. Тест создаёт заказ price=0, SQL вернул 0. Для заказа №${n} какое ожидание?`,'Успех с сохранённым нулём','Отказ из-за false-подобного значения','Замена на NULL','Удаление заказа'));
add('integration-qa','qa-version-conflict-no-write',3,IQ,n=>Q(`Автотест отправил старую version=${n}; SQL хранит version=${n+1}. Корректный отказ не меняет строку. Введите ожидаемую version после.`,n+1));
