add('integration-mle','mle-python-invalid-finite-values',2,['python','ml-engineering'],n=>Q(`Python проверяет isfinite для входа [${n}, NaN, Infinity, 0]. Сколько значений не проходят эту проверку?`,2));
add('integration-mle','mle-python-canary-share',2,IM,n=>Q(`Python router направляет 5% из ${n*100} запросов новой ML-модели. Сколько запросов у canary?`,n*5));
add('integration-mle','mle-python-retry-quota-once',2,['python','ml-engineering'],n=>Q(`Python inference API: квота 100, эффект списания ${n} за ключ; получено 3 последовательных повтора одного ключа с дедупликацией. Введите остаток.`,100-n));
add('integration-mle','mle-python-feature-order-contract',2,IM,n=>C(`ML ждёт [age,income]; Python вход [income,age] для объекта №${n}. Как восстановить правильный вход?`,'Переупорядочить по именованной схеме','Сортировать числа по величине','Не менять порядок','Считать признаки симметричными всегда'));
add('integration-mle','mle-python-train-serving-mismatch',3,IM,n=>C(`Python training делит x на ${n}, serving делит на ${n+1}, веса одинаковые. Что возникает?`,'Train-serving skew преобразований','Гарантированное улучшение качества','Только изменение latency','Нулевая разница входов всегда'));
add('integration-mle','mle-python-feature-asof',3,IM,n=>Q(`Python строит ML-признаки для t=${n*10}. Записи доступны в t=${n*10-2}, ${n*10-1}, ${n*10+1}. Сколько допустимо по point-in-time?`,2));
add('integration-mle','mle-python-padding-tokens',3,IM,n=>Q(`Python формирует ML batch длин ${n}, ${n+2}, ${n+4}, padding до максимума. Сколько добавлено токенов?`,6));
add('integration-mle','mle-python-label-join-version',3,IM,n=>C(`Python мониторинг смешал прогнозы v${n} и v${n+1}, метки связаны по id. Что нужно для сравнения качества версий?`,'Группировать по сохранённой версии и сопоставимым зрелым данным','Считать все версии одной без различий','Заменить метки прогнозами','Сравнить только имена файлов'));
add('integration-mle','mle-python-drift-not-groundtruth',3,IM,n=>C(`Python мониторинг увидел drift у ${n}% ML-входов без меток. Доказывает ли это падение accuracy?`,'Нет, это сигнал для проверки качества, а не сама оценка accuracy','Да, accuracy всегда 0','Да, latency и accuracy одинаковы','Да, drift заменяет метки'));
add('integration-mle','mle-python-service-threshold-version',3,IM,n=>C(`Python API меняет порог модели v${n}, веса прежние. Что версионировать для воспроизводимого класса?`,'Веса, preprocessing и правило порога','Только веса','Только число процессов','Только URL README'));
add('integration-mle','mle-python-delayed-label-missing',3,IM,n=>C(`Метки приходят через ${n} дней. Python получил None для вчерашних прогнозов. Как учитывать при оценке accuracy?`,'Не подменять None отрицательным классом; ждать зрелые метки','Считать None верным прогнозом','Считать None равным нулю всегда','Удалить все вчерашние прогнозы без истории'));
add('integration-mle','mle-python-queue-saturation',3,['python','ml-engineering'],n=>C(`У Python serving ${n} занятых воркера и полная ограниченная очередь. Как не допустить неограниченного расхода памяти?`,'Backpressure или контролируемый отказ','Неограниченная очередь','Загрузка новой модели на каждый запрос','Отключение deadline'));
add('integration-mle','mle-python-cache-cross-version',3,IM,n=>C(`Python кеш keyed только входом, модель обновлена v${n}→v${n+1}. Что устранит выдачу старых прогнозов под новой версией?`,'Включить версии модели/preprocessing в ключ или корректно инвалидировать','Изменить только favicon','Удалить версию из ответа','Считать все модели эквивалентными'));
add('integration-mle','mle-python-mse-monitor',3,['python','ml','ml-engineering'],n=>Q(`Python production-мониторинг на зрелых метках получил ошибки модели [${n},-${n}]. MSE=mean(error²). Введите MSE.`,n*n));
add('automation','spy-restoration-after-test',3,1,n=>C(`Тест №${n} заменил метод общего объекта spy-обёрткой. Что сделать в гарантированном teardown?`,'Восстановить исходный метод','Оставить spy для всех следующих тестов','Удалить весь объект','Добавить ещё один spy'));
